import React, { useState } from "react";
import Registration from "./Registration";
import SafetyCheck from "./SafetyCheck";
import RoutePlanner from "./RoutePlanner";

function App() {
  const [step, setStep] = useState("registration"); // registration → safety → route
  const [tourist, setTourist] = useState(null);

  // Step 1: Registration
  if (step === "registration") {
    return (
      <Registration
        onRegistered={(data) => {
          setTourist(data);
          setStep("safety");
        }}
      />
    );
  }

  // Step 2: Safety Check
  if (step === "safety") {
    return (
      <SafetyCheck
        tourist={tourist}
        onSafetyChecked={() => setStep("route")}
      />
    );
  }

  // Step 3: Route Planner
  if (step === "route") {
    return <RoutePlanner tourist={tourist} />;
  }

  return null;
}

export default App;
